import { StyleSheet, Text, View } from 'react-native';

import { theme } from '../theme';

type AvatarProps = {
  displayName?: string | null;
  avatarColor?: string | null;
  size?: 40 | 48;
};

type Palette = {
  accent: string;
  text: string;
};

const themeValue = theme as unknown as Palette & { colors?: Palette };
const colors = themeValue.colors ?? themeValue;

function getInitials(displayName?: string | null) {
  const words = displayName?.trim().split(/\s+/).filter(Boolean) ?? [];

  if (words.length === 0) {
    return '?';
  }

  return words
    .slice(0, 2)
    .map((word) => word[0])
    .join('')
    .toLocaleUpperCase();
}

export function Avatar({ displayName, avatarColor, size = 48 }: AvatarProps) {
  return (
    <View
      accessibilityLabel={`Аватар ${displayName?.trim() || 'пользователя'}`}
      style={[
        styles.avatar,
        {
          width: size,
          height: size,
          borderRadius: size / 2,
          backgroundColor: avatarColor || colors.accent,
        },
      ]}
    >
      <Text style={[styles.initials, { color: colors.text, fontSize: size === 40 ? 14 : 16 }]}>
        {getInitials(displayName)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  avatar: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  initials: {
    fontWeight: '700',
    letterSpacing: 0.3,
  },
});
