import { Pressable, StyleSheet, Text, View } from 'react-native';

import type { Chat } from '../api/types';
import { theme } from '../theme';
import { Avatar } from './Avatar';

type ChatListItemProps = {
  chat: Chat;
  onPress: () => void;
};

type ChatView = {
  id: string;
  title?: string | null;
  displayName?: string | null;
  avatarColor?: string | null;
  lastMessage?: {
    text?: string | null;
    type?: string | null;
    createdAt?: string | null;
  } | null;
  updatedAt?: string | null;
  unreadCount?: number;
  muted?: boolean;
};

type Palette = {
  bg: string;
  surface: string;
  accent: string;
  text: string;
  muted?: string;
  textMuted?: string;
  divider?: string;
};

const themeValue = theme as unknown as Palette & { colors?: Palette };
const colors = themeValue.colors ?? themeValue;
const mutedColor = colors.textMuted ?? colors.muted ?? '#8B9BB4';

export function getChatTitle(chat: Chat) {
  const value = chat as unknown as ChatView;
  return value.displayName?.trim() || value.title?.trim() || 'Чат';
}

function getPreview(chat: ChatView) {
  const message = chat.lastMessage;

  if (!message) {
    return 'Нет сообщений';
  }

  const preview = message.text?.trim() || 'Аудиосообщение';
  return chat.muted ? `Без звука · ${preview}` : preview;
}

function getTime(value?: string | null) {
  if (!value) {
    return '';
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}

export function ChatListItem({ chat, onPress }: ChatListItemProps) {
  const value = chat as unknown as ChatView;
  const title = getChatTitle(chat);
  const unreadCount = Math.max(0, value.unreadCount ?? 0);
  const timestamp = getTime(value.lastMessage?.createdAt ?? value.updatedAt);

  return (
    <Pressable
      accessibilityLabel={`${title}. ${getPreview(value)}`}
      accessibilityRole="button"
      onPress={onPress}
      style={({ pressed }) => [styles.row, pressed && styles.pressed]}
    >
      <Avatar displayName={title} avatarColor={value.avatarColor} size={48} />
      <View style={styles.content}>
        <View style={styles.topLine}>
          <Text numberOfLines={1} style={styles.title}>
            {title}
          </Text>
          <Text style={[styles.time, unreadCount > 0 && styles.activeTime]}>{timestamp}</Text>
        </View>
        <View style={styles.bottomLine}>
          <Text numberOfLines={1} style={styles.preview}>
            {getPreview(value)}
          </Text>
          {unreadCount > 0 ? (
            <View style={styles.badge}>
              <Text style={styles.badgeText}>{unreadCount > 99 ? '99+' : unreadCount}</Text>
            </View>
          ) : null}
        </View>
      </View>
    </Pressable>
  );
}

