} from 'react-native';

import { client } from '../api/client';
import type { Chat, User } from '../api/types';
import { Avatar } from '../components/Avatar';
import type { RootStackParamList } from '../navigation/types';
import { theme } from '../theme';

type Props = NativeStackScreenProps<RootStackParamList, 'NewChat'>;

type UserView = {
  id: string;
  username: string;
  displayName?: string | null;
  avatarColor?: string | null;
};

type ChatView = {
  id: string;
  title?: string | null;
  displayName?: string | null;
};

type Palette = {
  bg: string;
  surface: string;
  accent: string;
  text: string;
  muted?: string;
  textMuted?: string;
  danger?: string;
  divider?: string;
};

const themeValue = theme as unknown as Palette & { colors?: Palette };
const colors = themeValue.colors ?? themeValue;
const mutedColor = colors.textMuted ?? colors.muted ?? '#8B9BB4';

function normalizeUsers(response: unknown): User[] {
  if (Array.isArray(response)) {
    return response as User[];
  }

  if (response && typeof response === 'object' && 'users' in response) {
    const users = (response as { users?: unknown }).users;
    return Array.isArray(users) ? (users as User[]) : [];
  }

  return [];
}

function normalizeChat(response: unknown): ChatView {
  if (response && typeof response === 'object' && 'chat' in response) {
    return (response as { chat: Chat }).chat as unknown as ChatView;
  }

  return response as ChatView;
}

export function NewChatScreen({ navigation }: Props) {
  const [query, setQuery] = useState('');
  const [users, setUsers] = useState<User[]>([]);
  const [searching, setSearching] = useState(false);
  const [creatingUserId, setCreatingUserId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const normalizedQuery = query.trim();
    if (!normalizedQuery) {
      setUsers([]);
      setSearching(false);
      setError(null);
      return undefined;
    }

    let active = true;
    const timer = setTimeout(() => {
      setSearching(true);
      setError(null);
      void client
        .searchUsers(normalizedQuery)
        .then((response) => {
          if (active) {
            setUsers(normalizeUsers(response));
          }
        })
        .catch((caughtError: unknown) => {
          if (active) {
            setError(
              caughtError instanceof Error ? caughtError.message : 'Не удалось найти пользователей',
            );
          }
        })
        .finally(() => {
          if (active) {
            setSearching(false);
          }
        });
    }, 300);

    return () => {
      active = false;
      clearTimeout(timer);
    };
  }, [query]);

  const handleUserPress = async (user: User) => {
    const value = user as unknown as UserView;
    if (creatingUserId) {
      return;
    }

    setCreatingUserId(value.id);
    setError(null);

    try {
      const chat = normalizeChat(
        await client.createChat({ type: 'direct', memberIds: [value.id] }),
      );
      const title = chat.displayName?.trim() || chat.title?.trim() || value.displayName?.trim() || value.username;
      navigation.replace('Chat', { chatId: chat.id, title });
    } catch (caughtError) {
      setError(caughtError instanceof Error ? caughtError.message : 'Не удалось создать чат');
    } finally {
      setCreatingUserId(null);
    }
  };

  return (
    <View style={styles.screen}>
      <TextInput
        autoCapitalize="none"
        autoCorrect={false}
        onChangeText={setQuery}
        placeholder="Поиск пользователей"
        placeholderTextColor={mutedColor}
        returnKeyType="search"
        style={styles.searchInput}
        value={query}
      />
      {error ? <Text style={styles.error}>{error}</Text> : null}
      {searching ? <ActivityIndicator color={colors.accent} style={styles.loader} /> : null}
      <FlatList
        data={users}
        keyboardShouldPersistTaps="handled"
        keyExtractor={(item) => String((item as unknown as UserView).id)}
        ListEmptyComponent={
          query.trim() && !searching ? (
            <Text style={styles.emptyText}>Пользователи не найдены</Text>
          ) : null
        }
        renderItem={({ item }) => {
          const user = item as unknown as UserView;
          const title = user.displayName?.trim() || user.username;
          const creating = creatingUserId === user.id;

          return (
            <Pressable
              accessibilityRole="button"
              disabled={creatingUserId !== null}
              onPress={() => void handleUserPress(item)}
              style={({ pressed }) => [styles.userRow, pressed && styles.pressedRow]}
            >
              <Avatar displayName={title} avatarColor={user.avatarColor} size={40} />
              <View style={styles.userText}>
                <Text numberOfLines={1} style={styles.displayName}>
                  {title}
                </Text>
                <Text numberOfLines={1} style={styles.username}>
                  @{user.username}
                </Text>
              </View>
              {creating ? <ActivityIndicator color={colors.accent} /> : null}
            </Pressable>
          );
        }}
      />
    </View>
  );
}

